"""EN/ES interface language.

The default UI is English. Selecting Espanol translates the interface chrome
(labels, buttons, headers, tabs, stage names, help texts) via the catalog below,
recovered from the project's own translation history. t() returns the string
unchanged in English and the mapped Spanish otherwise, falling back to the English
text when a string is not in the catalog. Dynamic messages built with f-strings are
intentionally left in English.
"""
import streamlit as st

LANGUAGES = {"English": "en", "Español": "es"}


def get_lang() -> str:
    return st.session_state.get("lang", "en")


def t(text: str) -> str:
    """Translate a UI string to the active language (English is the source)."""
    if get_lang() == "en":
        return text
    return _ES.get(text, text)


